const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ShadingType,
  BorderStyle, LevelFormat, TabStopType, PageBreak
} = require("docx");

// ---------- palette ----------
const PLUM = "4A3B47";       // deep plum-charcoal band
const PLUM_TINT = "F4EFF1";  // soft tint
const GOLD = "9A7B4F";       // VIP band
const GOLD_TINT = "F7F1E7";  // VIP tint
const INK = "2B2329";        // body text
const SOFT = "8A7C84";       // muted
const RIGHT_TAB = 9360;      // content width (Letter, 1in margins)

// ---------- helpers ----------
const tierHeader = (name, price, bandColor) =>
  new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: bandColor },
    spacing: { before: 220, after: 0 },
    tabStops: [{ type: TabStopType.RIGHT, position: RIGHT_TAB }],
    children: [
      new TextRun({ text: name, bold: true, color: "FFFFFF", size: 26, font: "Arial" }),
      new TextRun({ text: "\t" + price, bold: true, color: "FFFFFF", size: 26, font: "Arial" }),
    ],
  });

const tagLine = (text, color) =>
  new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: color },
    spacing: { before: 0, after: 120 },
    children: [
      new TextRun({ text: text, italics: true, color: "FFFFFF", size: 18, font: "Arial" }),
    ],
  });

const subLabel = (text, color) =>
  new Paragraph({
    spacing: { before: 100, after: 40 },
    children: [new TextRun({ text: text, bold: true, color: color, size: 19, font: "Arial" })],
  });

const bullet = (text) =>
  new Paragraph({
    numbering: { reference: "b", level: 0 },
    spacing: { before: 10, after: 10 },
    children: [new TextRun({ text: text, color: INK, size: 19, font: "Arial" })],
  });

const valueLine = (text) =>
  new Paragraph({
    spacing: { before: 80, after: 140 },
    children: [new TextRun({ text: text, bold: true, color: PLUM, size: 19, font: "Arial" })],
  });

const divider = () =>
  new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D9CDD3", space: 1 } },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text: "", size: 2 })],
  });

// ---------- a location page ----------
function buildLocation(opts) {
  const kids = [];

  // Brand / location header band
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM },
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: opts.brand.toUpperCase(), bold: true, color: "E8DCE2", size: 18, font: "Arial", characterSpacing: 60 })],
  }));
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM },
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: opts.title, bold: true, color: "FFFFFF", size: 40, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM },
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: opts.subtitle, italics: true, color: "E8DCE2", size: 20, font: "Arial" })],
  }));
  // intro
  kids.push(new Paragraph({
    spacing: { before: 160, after: 60 },
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.intro, color: SOFT, size: 19, font: "Arial" })],
  }));

  // tiers
  opts.tiers.forEach((t, i) => {
    kids.push(tierHeader(t.name, t.price, t.band));
    kids.push(tagLine(t.tag, t.band));
    kids.push(subLabel(t.chooseLabel, t.band === GOLD ? GOLD : PLUM));
    t.choose.forEach(c => kids.push(bullet(c)));
    kids.push(subLabel(t.benefitLabel, t.band === GOLD ? GOLD : PLUM));
    t.benefits.forEach(b => kids.push(bullet(b)));
    kids.push(valueLine(t.value));
    if (i < opts.tiers.length - 1) kids.push(divider());
  });

  // how it works / terms
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM_TINT },
    spacing: { before: 160, after: 40 },
    children: [new TextRun({ text: "How Your Membership Works", bold: true, color: PLUM, size: 20, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [new TextRun({ text: opts.howItWorks, color: INK, size: 18, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: opts.terms, color: SOFT, size: 16, font: "Arial" })],
  }));

  // contact line
  kids.push(new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 200, after: 0 },
    children: [new TextRun({ text: opts.contact, bold: true, color: PLUM, size: 19, font: "Arial" })],
  }));

  return kids;
}

