const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ShadingType,
  BorderStyle, LevelFormat, TabStopType
} = require("docx");

const PLUM = "4A3B47";
const PLUM_TINT = "F4EFF1";
const GOLD = "9A7B4F";
const INK = "2B2329";
const SOFT = "8A7C84";
const RIGHT_TAB = 9360;

const pkgHeader = (name, price, band) =>
  new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: band },
    spacing: { before: 220, after: 0 },
    tabStops: [{ type: TabStopType.RIGHT, position: RIGHT_TAB }],
    children: [
      new TextRun({ text: name, bold: true, color: "FFFFFF", size: 26, font: "Arial" }),
      new TextRun({ text: "\t" + price, bold: true, color: "FFFFFF", size: 24, font: "Arial" }),
    ],
  });

const tagLine = (text, band) =>
  new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: band },
    spacing: { before: 0, after: 120 },
    children: [new TextRun({ text: text, italics: true, color: "FFFFFF", size: 18, font: "Arial" })],
  });

const subLabel = (text, color) =>
  new Paragraph({
    spacing: { before: 100, after: 40 },
    children: [new TextRun({ text: text, bold: true, color: color, size: 19, font: "Arial" })],
  });

const bullet = (text) =>
  new Paragraph({
    numbering: { reference: "b", level: 0 },
    spacing: { before: 10, after: 10 },
    children: [new TextRun({ text: text, color: INK, size: 19, font: "Arial" })],
  });

const lineRun = (label, value) =>
  new Paragraph({
    spacing: { before: 30, after: 30 },
    children: [
      new TextRun({ text: label + " ", bold: true, color: PLUM, size: 19, font: "Arial" }),
      new TextRun({ text: value, color: INK, size: 19, font: "Arial" }),
    ],
  });

const valueLine = (alacarte, save) =>
  new Paragraph({
    spacing: { before: 60, after: 30 },
    children: [
      new TextRun({ text: "À la carte value " + alacarte + ". ", color: SOFT, size: 18, font: "Arial" }),
      new TextRun({ text: "You save " + save + ".", bold: true, color: GOLD, size: 19, font: "Arial" }),
    ],
  });

const whyLine = (text) =>
  new Paragraph({
    spacing: { before: 20, after: 150 },
    children: [new TextRun({ text: "Why it works: " + text, italics: true, color: SOFT, size: 18, font: "Arial" })],
  });

const divider = () =>
  new Paragraph({
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D9CDD3", space: 1 } },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text: "", size: 2 })],
  });

function buildLocation(opts) {
  const kids = [];
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.brand.toUpperCase(), bold: true, color: "E8DCE2", size: 18, font: "Arial", characterSpacing: 60 })],
  }));
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: "Signature Packages", bold: true, color: "FFFFFF", size: 40, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.subtitle, italics: true, color: "E8DCE2", size: 20, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    spacing: { before: 160, after: 60 }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.intro, color: SOFT, size: 19, font: "Arial" })],
  }));

  opts.packages.forEach((p, i) => {
    kids.push(pkgHeader(p.name, p.price, p.band));
    kids.push(tagLine(p.tag, p.band));
    kids.push(subLabel("What's included:", p.band === GOLD ? GOLD : PLUM));
    p.included.forEach(c => kids.push(bullet(c)));
    kids.push(lineRun("Protocol:", p.protocol));
    kids.push(valueLine(p.alacarte, p.save));
    kids.push(whyLine(p.why));
    if (i < opts.packages.length - 1) kids.push(divider());
  });

  kids.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM_TINT }, spacing: { before: 160, after: 40 },
    children: [new TextRun({ text: "Good to Know", bold: true, color: PLUM, size: 20, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [new TextRun({ text: opts.note, color: INK, size: 18, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: opts.terms, color: SOFT, size: 16, font: "Arial" })],
  }));
  kids.push(new Paragraph({
    alignment: AlignmentType.CENTER, spacing: { before: 200, after: 0 },
    children: [new TextRun({ text: "Ready to begin? Book your complimentary consultation today.", bold: true, color: PLUM, size: 19, font: "Arial" })],
  }));
  return kids;
}

// ============================================================
// MEDFORD PACKAGES
// ============================================================
