    },
    {
      name: "The Timeless Lift", price: "$7,900", band: PLUM,
      tag: "A non surgical facial lift and full skin renewal. For visible firming, smoothing, and volume.",
      included: [
        "FaceTite or AccuTite for the face and neck, minimally invasive lifting and tightening",
        "Ignite RF fractional resurfacing, a series of 3, for deep dermal remodeling",
        "SkinPen microneedling, a series of 3, for collagen and texture",
        "A neuromodulator treatment to relax dynamic wrinkles",
        "One syringe of dermal filler to restore lost volume",
        "Three HydraFacials and a medical grade skincare regimen",
      ],
      protocol: "Four to six months, lift and tighten first, then resurface and refine.",
      alacarte: "$9,870", save: "$1,970, about 20%",
      why: "Tightening the foundation before resurfacing the surface produces a lifted, smooth result that holds, rather than treating texture on skin that is still lax.",
    },
    {
      name: "The Red Carpet Glow", price: "$3,500", band: PLUM,
      tag: "Event ready radiance. For brides, milestones, and every moment worth looking your best for.",
      included: [
        "Three Signature HydraFacials timed to your event",
        "Two SkinPen microneedling sessions for a flawless canvas",
        "A light neuromodulator treatment to soften fine lines",
        "One syringe of lip or cheek filler for a fresh, natural finish",
        "An esthetician facial with dermaplaning the week of your event",
        "EMSCULPT NEO, two sessions, for a toned silhouette",
        "An event day spray tan and a take home skincare kit",
      ],
      protocol: "Eight to twelve weeks before your event, building to a peak the week of.",
      alacarte: "$4,390", save: "$890, about 20%",
      why: "Skin perfecting treatments need lead time to settle, so the protocol front loads the work and lands the glow exactly when the cameras come out.",
    },
  ],
  note: "Members apply their tier discount to any package, and package balances can be paid down using your Treatment Bank credits.",
  terms: "Investment figures are illustrative, based on typical regional pricing. Confirm against the practice's à la carte rates. Treatment plans are personalized at consultation and may be adjusted for candidacy and goals.",
};

// ============================================================
// CINNAMINSON PACKAGES
// ============================================================
const cinnaminson = {
  brand: "[ Your Practice Name ]",
  subtitle: "Cinnaminson",
  intro: "Curated treatment journeys that combine our advanced laser, light, and energy technologies into one outcome, at one bundled investment.",
  packages: [
    {
      name: "The Lift & Firm", price: "$4,700", band: GOLD,
      tag: "Our flagship tightening journey. For laxity, jowls, and fine lines, without surgery.",
      included: [
        "Virtue RF robotic precision microneedling, a series of 3, for collagen and elastin",
        "A PDO thread lift of the lower face for immediate structural lifting",
        "A neuromodulator treatment to smooth dynamic wrinkles",
        "One syringe of dermal filler to restore contour and support",
        "One Pico or Envision IPL session to even tone and clarity",
        "A medical grade skincare regimen to protect your results",
      ],
      protocol: "Four to six months, threads for instant lift, Virtue RF for long term remodeling.",
      alacarte: "$5,920", save: "$1,220, about 21%",
      why: "Threads deliver lift today while Virtue RF rebuilds collagen underneath over the following months, so the result keeps improving long after the first visit.",
    },
    {
      name: "The Flawless Complexion", price: "$3,150", band: PLUM,
