const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ShadingType,
  BorderStyle, LevelFormat, TabStopType
} = require("docx");

const PLUM = "4A3B47";
const PLUM_TINT = "F4EFF1";
const GOLD = "9A7B4F";
const GOLD_TINT = "F7F1E7";
const INK = "2B2329";
const SOFT = "8A7C84";
const RIGHT_TAB = 9360;

const bullet = (text) =>
  new Paragraph({
    numbering: { reference: "b", level: 0 },
    spacing: { before: 10, after: 10 },
    children: [new TextRun({ text: text, color: INK, size: 19, font: "Arial" })],
  });

const qHeader = (text) =>
  new Paragraph({
    spacing: { before: 130, after: 30 },
    children: [new TextRun({ text: text, bold: true, color: GOLD, size: 20, font: "Arial" })],
  });

const sectionLabel = (text) =>
  new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM_TINT },
    spacing: { before: 150, after: 40 },
    children: [new TextRun({ text: text, bold: true, color: PLUM, size: 20, font: "Arial" })],
  });

function build(opts) {
  const k = [];

  // brand band
  k.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: GOLD }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.brand.toUpperCase(), bold: true, color: "F7F1E7", size: 18, font: "Arial", characterSpacing: 60 })],
  }));
  k.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: GOLD }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: "The Signature Year", bold: true, color: "FFFFFF", size: 44, font: "Arial" })],
  }));
  k.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: GOLD }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.subtitle + "  |  Our Most Complete Transformation", italics: true, color: "F7F1E7", size: 20, font: "Arial" })],
  }));

  // price band
  k.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    children: [
      new TextRun({ text: "$12,000 for the year", bold: true, color: "FFFFFF", size: 30, font: "Arial" }),
      new TextRun({ text: "      or just $1,000 per month", color: "E8DCE2", size: 24, font: "Arial" }),
    ],
  }));

  // intro
  k.push(new Paragraph({
    spacing: { before: 160, after: 60 }, alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: opts.intro, color: SOFT, size: 19, font: "Arial" })],
  }));

  // quarters
  k.push(sectionLabel("Your Year, Quarter by Quarter"));
  opts.quarters.forEach(q => {
    k.push(qHeader(q.title));
    q.items.forEach(it => k.push(bullet(it)));
  });

  // included all year
  k.push(sectionLabel("Included Every Month, All Year"));
  opts.allYear.forEach(it => k.push(bullet(it)));

  // concierge
  k.push(sectionLabel("Your Concierge Privileges"));
  opts.concierge.forEach(it => k.push(bullet(it)));

  // value stack
  k.push(new Paragraph({
    shading: { type: ShadingType.CLEAR, fill: GOLD_TINT }, spacing: { before: 160, after: 30 },
    children: [
      new TextRun({ text: "À la carte value " + opts.alacarte + ".  ", color: INK, size: 20, font: "Arial" }),
      new TextRun({ text: "Your investment $12,000.  ", bold: true, color: PLUM, size: 20, font: "Arial" }),
      new TextRun({ text: "You save " + opts.save + ".", bold: true, color: GOLD, size: 20, font: "Arial" }),
    ],
  }));
  k.push(new Paragraph({
    spacing: { before: 0, after: 40 },
    children: [new TextRun({ text: "Spread across twelve months at $1,000, or finance through our partners. No large payment up front.", color: INK, size: 18, font: "Arial" })],
  }));
  if (opts.optional) {
    k.push(new Paragraph({
      spacing: { before: 0, after: 40 },
      children: [new TextRun({ text: opts.optional, italics: true, color: SOFT, size: 18, font: "Arial" })],
    }));
  }
  k.push(new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "Investment figures are illustrative, based on typical regional pricing. Confirm against the practice's à la carte rates. Plans are personalized at consultation and adjusted for candidacy and goals.", color: SOFT, size: 15, font: "Arial" })],
  }));

  k.push(new Paragraph({
    alignment: AlignmentType.CENTER, spacing: { before: 200, after: 0 },
    children: [new TextRun({ text: "Limited enrollment. Reserve your year with a complimentary consultation.", bold: true, color: GOLD, size: 20, font: "Arial" })],
  }));
  return k;
}

// ============================================================ MEDFORD
const medford = {
  brand: "[ Your Practice Name ]",
  subtitle: "Medford",
  intro: "A full body, face, and wellness transformation, guided over twelve months and sequenced for results that build on each other.",
  quarters: [
    { title: "Quarter 1, Foundation and Reset", items: [
      "Enroll in a twelve month medical weight loss program with a supervised protocol",
      "Begin peptide therapy to support metabolism and recovery",
      "EMSCULPT NEO, your first four sessions, to start reducing fat and building muscle",
      "A baseline assessment and your custom medical grade skincare regimen",
    ]},
    { title: "Quarter 2, Sculpt and Define", items: [
      "BodyTite or AccuTite on one major zone, surgical grade tightening without surgery",
      "EMSCULPT NEO, your second four sessions, to lock in your new contour",
      "Monthly HydraFacials continue throughout",
    ]},
    { title: "Quarter 3, Lift and Renew", items: [
      "FaceTite or AccuTite for the face and neck, or a full Ignite RF resurfacing series",
      "SkinPen microneedling, a series of four, for collagen and texture",
      "A neuromodulator treatment and one syringe of dermal filler",
    ]},
    { title: "Quarter 4, Refine and Reveal", items: [
      "A quarterly injectable refresh and a second syringe of filler as needed",
      "A final SkinPen polish and continued monthly facials",
      "Two spray tans and a professional before and after reveal session",
    ]},
  ],
  allYear: [
    "A Signature HydraFacial or custom facial every single month",
    "Your medical grade skincare regimen, replenished each quarter",
    "Quarterly neuromodulator touch ups to stay refreshed year round",
  ],
  concierge: [
    "A dedicated concierge line and same week priority scheduling",
    "25% member pricing on anything outside your plan, including guests",
    "First access to new technology and invitations to private VIP events",
    "Premium birthday and anniversary gifts",
    "Quarterly progress reviews with professional photography",
  ],
  alacarte: "$18,000",
  save: "$6,000, about 33%",
  optional: null,
};

// ============================================================ CINNAMINSON
const cinnaminson = {
  brand: "[ Your Practice Name ]",
  subtitle: "Cinnaminson",
  intro: "A full year of advanced laser, light, and tightening, guided from clear, even skin to lasting lift and refinement.",
  quarters: [
    { title: "Quarter 1, Clear and Correct", items: [
      "Pico laser series begins for pigment and melasma",
      "Envision IPL series begins for redness and vascular clarity",
      "Cervello laser hair removal series begins on one large region",
      "A baseline assessment and your custom medical grade skincare regimen",
    ]},
    { title: "Quarter 2, Resurface", items: [
      "CO2 laser resurfacing, one full treatment, or a CoolPeel series for lower downtime",
      "Suprema laser sessions for multi wavelength correction",
      "Monthly skin treatments continue throughout",
    ]},
    { title: "Quarter 3, Lift and Firm", items: [
      "Virtue RF robotic microneedling, a series of four, for collagen and elastin",
      "A PDO thread lift of the lower face for structural lifting",
      "A neuromodulator treatment and one syringe of dermal filler",
    ]},
    { title: "Quarter 4, Refine and Reveal", items: [
      "A quarterly injectable refresh and a second syringe of filler as needed",
      "A final Pico or Envision IPL polish for even tone",
      "A professional before and after reveal session",
    ]},
  ],
  allYear: [
    "A signature laser or skin treatment every single month",
    "Your medical grade skincare regimen, replenished each quarter",
    "Quarterly neuromodulator touch ups to stay refreshed year round",
  ],
  concierge: [
    "A dedicated concierge line and same week priority scheduling",
    "25% member pricing on anything outside your plan, including guests",
    "First access to new technology and invitations to private VIP events",
    "Premium birthday and anniversary gifts",
    "Quarterly progress reviews with professional photography",
  ],
  alacarte: "$18,500",
  save: "$6,500, about 35%",
  optional: "Optional add on: a men's vitality track built around Gainswave and Omniwave can be layered into the year.",
};

function makeDoc(loc) {
  return new Document({
    styles: { default: { document: { run: { font: "Arial", size: 19, color: INK } } } },
    numbering: { config: [{ reference: "b", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 360, hanging: 220 } } } }] }] },
    sections: [{
      properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 } } },
      children: build(loc),
    }],
  });
}

Packer.toBuffer(makeDoc(medford)).then(b =>
  fs.writeFileSync("/mnt/user-data/outputs/Medford_The_Signature_Year.docx", b));
Packer.toBuffer(makeDoc(cinnaminson)).then(b =>
  fs.writeFileSync("/mnt/user-data/outputs/Cinnaminson_The_Signature_Year.docx", b));
console.log("done");

