const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, ShadingType,
  BorderStyle, LevelFormat, TabStopType
} = require("docx");

const PLUM = "4A3B47", PLUM_TINT = "F4EFF1", GOLD = "9A7B4F", GOLD_TINT = "F7F1E7";
const INK = "2B2329", SOFT = "8A7C84", RIGHT_TAB = 9360;

const bullet = (t) => new Paragraph({
  numbering: { reference: "b", level: 0 }, spacing: { before: 10, after: 10 },
  children: [new TextRun({ text: t, color: INK, size: 19, font: "Arial" })],
});
const head = (name, price, band) => new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: band }, spacing: { before: 220, after: 0 },
  tabStops: [{ type: TabStopType.RIGHT, position: RIGHT_TAB }],
  children: [
    new TextRun({ text: name, bold: true, color: "FFFFFF", size: 26, font: "Arial" }),
    new TextRun({ text: "\t" + price, bold: true, color: "FFFFFF", size: 24, font: "Arial" }),
  ],
});
const tag = (t, band) => new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: band }, spacing: { before: 0, after: 120 },
  children: [new TextRun({ text: t, italics: true, color: "FFFFFF", size: 18, font: "Arial" })],
});
const lab = (t, c) => new Paragraph({
  spacing: { before: 100, after: 40 },
  children: [new TextRun({ text: t, bold: true, color: c, size: 19, font: "Arial" })],
});
const value = (alc, save) => new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: GOLD_TINT }, spacing: { before: 70, after: 30 },
  children: [
    new TextRun({ text: "À la carte value " + alc + ".  ", color: INK, size: 19, font: "Arial" }),
    new TextRun({ text: "You save " + save + ".", bold: true, color: GOLD, size: 19, font: "Arial" }),
  ],
});
const pay = (t) => new Paragraph({
  spacing: { before: 0, after: 30 },
  children: [new TextRun({ text: t, color: SOFT, size: 17, font: "Arial" })],
});
const why = (t) => new Paragraph({
  spacing: { before: 10, after: 150 },
  children: [new TextRun({ text: "Why it works: " + t, italics: true, color: SOFT, size: 18, font: "Arial" })],
});
const div = () => new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D9CDD3", space: 1 } },
  spacing: { before: 40, after: 40 }, children: [new TextRun({ text: "", size: 2 })],
});
const qh = (t) => new Paragraph({
  spacing: { before: 120, after: 30 },
  children: [new TextRun({ text: t, bold: true, color: GOLD, size: 19, font: "Arial" })],
});
const sect = (t) => new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: PLUM_TINT }, spacing: { before: 140, after: 40 },
  children: [new TextRun({ text: t, bold: true, color: PLUM, size: 19, font: "Arial" })],
});

const k = [];

// Title
k.push(new Paragraph({ shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "[ YOUR PRACTICE NAME ]", bold: true, color: "E8DCE2", size: 18, font: "Arial", characterSpacing: 60 })] }));
k.push(new Paragraph({ shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "Signature Packages", bold: true, color: "FFFFFF", size: 40, font: "Arial" })] }));
k.push(new Paragraph({ shading: { type: ShadingType.CLEAR, fill: PLUM }, alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "Curated journeys, priced for real savings", italics: true, color: "E8DCE2", size: 20, font: "Arial" })] }));
k.push(new Paragraph({ spacing: { before: 160, after: 60 }, alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "Each package combines our most effective treatments toward one outcome, at one bundled investment below à la carte.", color: SOFT, size: 19, font: "Arial" })] }));

// ---- Package 1: Glow
k.push(head("The Glow Package", "$3,200", PLUM));
k.push(tag("Camera ready radiance for an event, a season, or a reset.", PLUM));
k.push(lab("What's included:", PLUM));
["CoolPeel laser resurfacing, a package of 3",
 "25 units of neurotoxin, Botox, Dysport, or Xeomin",
 "One syringe of lip filler",
 "One IPL photofacial for sun spots and even tone"].forEach(x => k.push(bullet(x)));
k.push(value("$3,935", "$735, about 19%"));
k.push(pay("Payable in full, or across 3 monthly payments. Financing available."));
k.push(why("Every treatment here is low downtime and high margin, sequenced so your skin peaks right when you need it."));
k.push(div());

// ---- Package 2: Body Sculpt
k.push(head("The Body Sculpt Package", "$7,500", PLUM));
k.push(tag("A full body recomposition, guided from the inside out.", PLUM));
k.push(lab("What's included:", PLUM));
["A 3 month medical weight loss program: Semaglutide, three MIC shots, nutritional guidance, and a meal plan guide",
 "BodyTite on one target area for surgical grade tightening without surgery",
 "RF microneedling for the treated area, a package of 3"].forEach(x => k.push(bullet(x)));
k.push(value("$8,960", "$1,460, about 16%"));
k.push(pay("Payable in full, or across 6 monthly payments. Financing available."));
k.push(why("Weight loss comes first, then BodyTite tightens, then microneedling smooths the skin over the new contour, in the order the body needs."));
k.push(div());

// ---- Package 3: Signature Lift
k.push(head("The Signature Lift Package", "$8,500", PLUM));
k.push(tag("Our most powerful non surgical lift, a true step above injectables alone.", PLUM));
k.push(lab("What's included:", PLUM));
["FaceTite for combined jowls and submental, minimally invasive lifting and tightening",
 "RF microneedling, full face and neck, a package of 3",
 "One syringe of dermal filler and 40 units of neurotoxin",
 "A PRP treatment to speed healing and add glow"].forEach(x => k.push(bullet(x)));
k.push(value("$10,170", "$1,670, about 16%"));
k.push(pay("Payable in full, or across 6 monthly payments. Financing available."));
k.push(why("FaceTite tightens the foundation, microneedling and PRP rebuild the surface, and injectables refine. It sits above the injectable facelift as the device driven tier."));
k.push(div());

// ---- FLAGSHIP: The Signature Year
k.push(head("The Signature Year", "$12,000  /  $1,000 per month", GOLD));
k.push(tag("Our most complete transformation, guided across twelve months.", GOLD));
k.push(sect("Your Year, Quarter by Quarter"));
k.push(qh("Quarter 1, Reset and Clarify"));
["Begin a 3 month medical weight loss program: Semaglutide, MIC shots, nutrition and a meal plan",
 "CoolPeel laser resurfacing begins, a package of 3",
 "Baseline assessment and your medical grade skincare regimen"].forEach(x => k.push(bullet(x)));
k.push(qh("Quarter 2, Resurface and Correct"));
["IPL photofacial series for sun spots and tone, a package of 4",
 "PRP facial series begins, a package of 3",
 "A quarterly neurotoxin refresh"].forEach(x => k.push(bullet(x)));
k.push(qh("Quarter 3, Lift and Tighten"));
["FaceTite for combined jowls and submental",
 "RF microneedling, full face and neck, a package of 4",
 "One syringe of dermal filler"].forEach(x => k.push(bullet(x)));
k.push(qh("Quarter 4, Refine and Reveal"));
["A quarterly neurotoxin refresh and a second syringe of filler as needed",
 "A final laser polish for even tone",
 "A professional before and after reveal session"].forEach(x => k.push(bullet(x)));
k.push(sect("Included Every Quarter, All Year"));
["A neurotoxin refresh each quarter to stay refreshed year round",
 "Your medical grade skincare, replenished each quarter",
 "Priority booking and first access to new technology"].forEach(x => k.push(bullet(x)));
k.push(value("$20,180", "$8,180, about 40%"));
k.push(pay("Twelve monthly payments of $1,000, with no large payment up front. Financing available."));
k.push(why("It is weighted toward high margin recurring treatments with the device work spread across the year, so it stays profitable while delivering the deepest savings we offer in exchange for the full year commitment."));

// footer
k.push(new Paragraph({ shading: { type: ShadingType.CLEAR, fill: PLUM_TINT }, spacing: { before: 160, after: 40 },
  children: [new TextRun({ text: "Good to Know", bold: true, color: PLUM, size: 20, font: "Arial" })] }));
k.push(new Paragraph({ spacing: { before: 0, after: 40 },
  children: [new TextRun({ text: "Aesthetics Renewal members apply their tier discount to any package. À la carte values are drawn from the current practice price list, and bundle savings are set against each treatment's margin, so every package protects profit.", color: INK, size: 18, font: "Arial" })] }));
k.push(new Paragraph({ spacing: { before: 0, after: 0 },
  children: [new TextRun({ text: "Treatment plans are personalized at consultation and adjusted for candidacy and goals. Areas shown are examples and may be substituted for equivalent value.", color: SOFT, size: 16, font: "Arial" })] }));
k.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 200, after: 0 },
  children: [new TextRun({ text: "Ready to begin? Book your complimentary consultation today.", bold: true, color: PLUM, size: 19, font: "Arial" })] }));

const doc = new Document({
  styles: { default: { document: { run: { font: "Arial", size: 19, color: INK } } } },
  numbering: { config: [{ reference: "b", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 360, hanging: 220 } } } }] }] },
  sections: [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 } } }, children: k }],
});
Packer.toBuffer(doc).then(b => fs.writeFileSync("/mnt/user-data/outputs/Signature_Packages_Real_Pricing.docx", b));
console.log("done");

